1: import type { QueueState } from "./queue";
2: export const statusVisuals = {
3:   idle: { label: "Start", path: "renderer-successor/assets/start.svg", frames: 1 },
4:   running: { label: "Working", path: "renderer-successor/assets/working.png", frames: 4 },
5:   paused: { label: "Paused", path: "renderer-successor/assets/paused.png", frames: 1 },
6:   succeeded: { label: "Ready", path: "renderer-successor/assets/ready-confirmed.png", frames: 1 },
7:   failed: { label: "Retry", path: "renderer-successor/assets/error-retry.png", frames: 1 },
8: };
9: export const display = { cell: [16, 16], scale: 3, filter: "nearest", frameMs: 100, background: "#172336" };
10: export function statusCell(state: QueueState) { return statusVisuals[state]; }
11: export function compactStatus(state: QueueState) { return statusVisuals[state]; }
12: export function accountBadge(registry: Record<string, string>, account: string) {
13:   return registry[account]; // Provided by the service; not enumerable in this checkout.
14: }
15: 
16: // Successor preserves descriptors and sheet geometry. Reduced motion changes the
17: // selected cell, never the backend state, label, asset identity or sheet dimensions.
18: export const motionQuery = "(prefers-reduced-motion: reduce)";
19: export function statusFrame(state: QueueState, elapsed: number, reducedMotion: boolean) {
20:   if (state === "running" && reducedMotion) return 0;
21:   return Math.floor(Math.max(0, elapsed) / display.frameMs) % statusVisuals[state].frames;
22: }
