24:     const image = new Image();
25:     const url = URL.createObjectURL(new Blob([data], { type: response.headers.get('Content-Type') }));
26:     try { image.src = url; await image.decode(); }
27:     finally { URL.revokeObjectURL(url); }
28:     return { available: true, image, path, sha256: await digest(data), width: image.naturalWidth, height: image.naturalHeight };
29:   })());
